/**  Executor가 성공했을 때 돌려주는 값. DB(result_json)에 그대로 저장된다. */
export type TaskOutput = 
/**  생성된 텍스트 원문 (게임 대화 등 호출자가 직접 후처리하는 경우) */
{ kind: "text"; content: string } | 
/**  DB에 저장된 메시지 */
{ kind: "message"; messageId: string; content: string } | 
/**  DB에 저장된 메시지 여러 개 (저장 순서대로) */
{ kind: "messages"; messageIds: string[] } | { kind: "image"; assetId: string } | { kind: "sync"; syncedCount: number } | { kind: "memory"; summary: string } | { kind: "empty" };

/**  작업을 요청한 쪽. 프론트가 어느 화면에 결과를 붙일지 고를 때 쓴다. */
export type TaskOwner = "chat" | "game" | "image" | "system";

/**  작업 상태. 전이 규칙은 task_state.rs에 있다. */
export type TaskStatus = 
/**  실행 대기 (큐에 들어갔지만 실행 슬롯을 아직 못 받음) */
"pending" | 
/**  실행 중 (attempt가 하나 열려 있음) */
"running" | 
/**  정상 완료 */
"completed" | 
/**  실패 (재시도 횟수 소진 또는 재시도 불가 오류) */
"failed" | 
/**  사용자 취소 / 복구 포기 */
"cancelled" | 
/**  앱·서비스 종료로 중단. 사용자가 재개(resume)하거나 포기(dismiss)할 수 있다. */
"interrupted";

/**  작업 종류. 종류마다 TaskExecutor가 하나씩 등록된다. */
export type TaskType = 
/**  일반 채팅 응답 생성 (ChatManager) */
"chat_stream" | 
/**  게임 NPC/씬 대화 생성 (GameRuntime) */
"game_dialogue" | 
/**  이미지 생성 (ImageManager) */
"image_gen" | "background_sync" | "memory_summary" | "embedding" | 
/**  번역 (코어 플러그인) */
"translate" | 
/**  음성 읽기 (코어 플러그인) */
"tts" | 
/**  API 연결 확인 등 설정 화면의 짧은 호출 */
"api_call";

